// The class of an algorithm: the high byte of its identifier. An identifier decoded from bytes may
// carry a class byte outside this enumeration; no code accepts one.
enum class AlgorithmClass : u8
{
    HybridKeyExchange    = 0x01U, // post-quantum/traditional hybrid key exchange
    ClassicalKeyExchange = 0x02U, // traditional elliptic-curve key exchange
    PostQuantumSignature = 0x03U, // post-quantum signature
    ClassicalSignature   = 0x04U, // traditional signature
    Aead                 = 0x05U, // authenticated encryption with associated data
    Kdf                  = 0x06U, // key derivation
};

[[nodiscard]] constexpr AlgorithmClass algorithm_class(AlgorithmId id) noexcept
{
    return static_cast<AlgorithmClass>(static_cast<u16>(id) >> 8U);
}

